+    public List<Attribute> output() {
+        if (lazyOutput == null) {
+            lazyOutput = Stream.concat(children().getFirst().output().stream(), subPlans.getFirst().output().stream()).distinct().toList();
+        }
+        return lazyOutput;
+    }
